with open(RAHU_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    capricorn_json = "\n      Capricorn: " + json.dumps(capricorn_data, indent=8) + ","
    new_content = content[:insertion_point] + capricorn_json + content[insertion_point:]
    
    with open(RAHU_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Rahu in Capricorn to rahu.js")
else:
    print("Could not find signs object in rahu.js")
